const b = ($input.first().json.body) || {};
const errs = [];
if (!b.name || !String(b.name).trim()) errs.push('name is required');
const slug = String(b.name || '').toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 14) || 'biz';
return [{ json: {
  ok: errs.length === 0, errors: errs,
  business_id: b.business_id || ('biz_' + slug),
  name: String(b.name || '').trim(),
  industry: b.industry || null,
  config: {
    tone: b.tone || 'friendly, professional, helpful',
    currency: b.currency || 'INR',
    timezone: b.timezone || 'Asia/Kolkata',
    city: b.city || null
  } } }];

const b = ($input.first().json.body) || {};
const bid = b.business_id;
let rows = [];
const errors = [];
const num = (v) => { const n = Number(String(v == null ? '' : v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : null; };
const mkSku = (name, i) => (String(name || 'item').toUpperCase().replace(/[^A-Z0-9]+/g, '').slice(0, 3) || 'ITM') + '-' + String(i + 1).padStart(3, '0');
if (Array.isArray(b.items)) {
  rows = b.items.map((it, i) => ({ raw: it, sku: it.sku || mkSku(it.name, i), name: it.name,
    category: it.category, price: num(it.price), currency: it.currency || 'INR',
    stock_qty: it.stock_qty == null ? 0 : Math.max(0, Math.round(num(it.stock_qty) || 0)),
    attributes: it.attributes && typeof it.attributes === 'object' ? it.attributes : {} }));
} else if (typeof b.csv === 'string' && b.csv.trim()) {
  const lines = b.csv.trim().split(/\r?\n/);
  const head = lines[0].split(',').map(h => h.trim().toLowerCase());
  lines.slice(1).forEach((ln, i) => {
    const cells = ln.split(',');
    const o = {}; head.forEach((h, k) => o[h] = (cells[k] || '').trim());
    rows.push({ raw: o, sku: o.sku || mkSku(o.name, i), name: o.name, category: o.category,
      price: num(o.price), currency: o.currency || 'INR',
      stock_qty: o.stock_qty === '' || o.stock_qty == null ? 0 : Math.max(0, Math.round(num(o.stock_qty) || 0)),
      attributes: {} });
  });
} else { errors.push('provide items[] or csv'); }
const valid = [], rejected = [];
for (const r of rows) {
  const why = [];
  if (!r.name) why.push('missing name');
  if (!r.category) why.push('missing category');
  if (r.price == null || r.price < 0) why.push('missing/invalid price');
  if (why.length) rejected.push({ row: r.raw, reasons: why }); else valid.push(r);
}
return [{ json: { ok: !!bid && valid.length > 0, business_id: bid, errors,
  valid, rejected, valid_count: valid.length, rejected_count: rejected.length } }];

const r = $input.first().json;
const p = $('Parse + Validate Catalog').first().json;
return [{ json: { ok: true, business_id: p.business_id, upserted: r.upserted, catalog_size: r.catalog_size,
  rejected_rows: p.rejected, note: p.rejected_count ? (p.rejected_count + ' row(s) rejected - see rejected_rows') : 'all rows loaded' } }];
